package XPerl::Installer::Proposal;

use strict;
use warnings;
use feature 'signatures';
use Digest::SHA;
use File::Compare qw(compare);
use File::Find;
use File::Spec;

sub files ($root) {
    my %files;
    File::Find::find({
        no_chdir => 1,
        wanted => sub {
            return unless -f $File::Find::name && !-l $File::Find::name;
            my $relative = substr($File::Find::name, length($root) + 1);
            $files{$relative} = 1;
        },
    }, $root);
    return \%files;
}

# Files generated by common Perl build systems cannot become portable source
# patches. A generated C file is identifiable when its XS input is present.
sub build_product ($class, $source, $relative) {
    return 1 if $relative =~ m{\A(?:blib|_build)(?:/|\z)};
    return 1 if $relative =~ m{(?:\A|/)(?:Makefile|Build|pm_to_blib|MYMETA\.(?:json|ya?ml))\z};
    return 1 if $relative =~ /\.(?:o|obj|so|bundle|dll|dylib|a|bs|bso|xsc)\z/i;
    if ($relative =~ /\A(.+)\.c\z/i) {
        return 1 if -f File::Spec->catfile($source, "$1.xs");
    }
    return 0;
}

# A repair agent may run the distribution's tests and leave arbitrary scratch
# files behind. Only source-shaped new files enter a portable patch. An entry
# added to MANIFEST also counts, unless it is a known build product.
sub patchable_new_file ($class, $source, $relative, $manifest) {
    return 0 if $class->work_product($relative);
    return 0 if $class->build_product($source, $relative);
    return 1 if $manifest->{$relative};
    return 0 unless $relative =~ m{\A(?:lib|t|xt|xs|bin|script|inc)/}
        || $relative !~ m{/};
    return $relative =~ /\.(?:pm|pl|t|xt|xs|h|c|pod|json|ya?ml|txt|ini|sh)\z/i;
}

# The whole namespace belongs to the installer and repair agent, including
# diagnostic notes whose contents and suffix are chosen by the agent.
sub work_product ($class, $relative) {
    return $relative =~ /\A\.xperl-repair-[0-9]+-[^\/]+\z/;
}

sub manifest_files ($class, $source) {
    my $path = File::Spec->catfile($source, 'MANIFEST');
    return {} unless -f $path;
    open my $input, '<', $path or die "cannot read $path: $!\n";
    my %files;
    while (my $line = <$input>) {
        my ($relative) = split /\s+/, $line;
        $files{$relative} = 1 if defined $relative && length $relative;
    }
    close $input or die "cannot close $path: $!\n";
    return \%files;
}

# Fingerprint only files that can enter the proposed patch. Build products
# already in the working tree must not make an unchanged repair look useful.
sub source_fingerprint ($class, %args) {
    my ($original, $source, $new_files) =
        @args{qw(original source new_files)};
    my $original_files = files($original);
    my %candidates = (%$original_files, %$new_files);
    my $digest = Digest::SHA->new(256);

    for my $relative (sort keys %candidates) {
        my $path = File::Spec->catfile($source, $relative);
        $digest->add($relative, "\0");
        unless (-f $path) {
            $digest->add("removed\0");
            next;
        }
        open my $input, '<:raw', $path
            or die "cannot read $path: $!\n";
        my $file_digest = Digest::SHA->new(256)->addfile($input)->hexdigest;
        close $input or die "cannot close $path: $!\n";
        $digest->add($file_digest, "\0");
    }
    return $digest->hexdigest;
}

sub write_patch ($class, %args) {
    my ($original, $source, $path, $new_files) =
        @args{qw(original source path new_files)};
    my $original_files = files($original);
    my $source_files = files($source);
    my %candidates = (%$original_files, %$new_files);
    open my $output, '>:raw', $path or die "cannot write $path: $!\n";
    my @changed;
    for my $relative (sort keys %candidates) {
        my $old = $original_files->{$relative}
            ? File::Spec->catfile($original, $relative) : undef;
        my $new = $source_files->{$relative}
            ? File::Spec->catfile($source, $relative) : undef;
        next unless $old || $new;
        if ($old && $new) {
            my $comparison = compare($old, $new);
            die "cannot compare $relative: $!\n" if $comparison < 0;
            next if $comparison == 0;
        }
        my $from = $old ? "a/$relative" : '/dev/null';
        my $to = $new ? "b/$relative" : '/dev/null';
        open my $diff, '-|', 'diff', '-u', '--label', $from,
            '--label', $to, $old // '/dev/null', $new // '/dev/null'
            or die "cannot start diff for $relative: $!\n";
        my $header = <$diff>;
        die "diff did not produce a patch for $relative\n"
            unless defined $header && $header =~ /^--- /;
        print {$output} $header;
        while (my $line = <$diff>) { print {$output} $line }
        close $diff;
        die "diff failed for $relative\n" unless $? >> 8 == 1;
        push @changed, $relative;
    }
    close $output or die "cannot close $path: $!\n";
    return { path => $path, files => \@changed } unless @changed;
    open my $input, '<:raw', $path or die "cannot read $path: $!\n";
    my $digest = Digest::SHA->new(256)->addfile($input)->hexdigest;
    return { path => $path, sha256 => $digest, files => \@changed };
}

1;
